    /// How `open` opens.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default)]
    pub struct OpenFlags(pub u32);

    impl OpenFlags {
        /// No flags.
        pub const NONE: OpenFlags = OpenFlags(0);
        /// Make the file if it does not exist (needs the write right); a
        /// directory fails with is_directory, and with `directory`
        /// invalid_argument, as Linux has it.
        pub const CREATE: OpenFlags = OpenFlags(1);
        /// With `create`: fail with exists if it does.
        pub const EXCLUSIVE: OpenFlags = OpenFlags(1 << 1);
        /// Cut the file to 0 bytes (needs the write right); a directory fails
        /// with is_directory.
        pub const TRUNCATE: OpenFlags = OpenFlags(1 << 2);
        /// Fail with not_directory unless it is a directory.
        pub const DIRECTORY: OpenFlags = OpenFlags(1 << 3);
        /// The description appends (radix-file(2)'s DescriptionFlags).
        pub const APPEND: OpenFlags = OpenFlags(1 << 4);
        /// The description does not wait (radix-file(2)'s DescriptionFlags).
        pub const NON_BLOCKING: OpenFlags = OpenFlags(1 << 5);
        /// Opening a terminal does not make it the controlling terminal of
        /// the caller's session.
        pub const NO_TERMINAL: OpenFlags = OpenFlags(1 << 6);
        /// The slot is emptied by radix-process(2)'s `exec`.
        pub const CLOSE_ON_EXEC: OpenFlags = OpenFlags(1 << 7);
        /// Fail with too_many_links if the last name is a symbolic link, as
        /// O_NOFOLLOW does.
        pub const NO_FOLLOW: OpenFlags = OpenFlags(1 << 8);
        /// Every flag.
        pub const ALL: OpenFlags = OpenFlags(0x1ff);
        /// Each flag and its name.
        pub const NAMES: [(OpenFlags, &'static str); 9] = [
            (OpenFlags::CREATE, "create"),
            (OpenFlags::EXCLUSIVE, "exclusive"),
            (OpenFlags::TRUNCATE, "truncate"),
            (OpenFlags::DIRECTORY, "directory"),
            (OpenFlags::APPEND, "append"),
            (OpenFlags::NON_BLOCKING, "non_blocking"),
            (OpenFlags::NO_TERMINAL, "no_terminal"),
            (OpenFlags::CLOSE_ON_EXEC, "close_on_exec"),
            (OpenFlags::NO_FOLLOW, "no_follow"),
        ];

        /// The flags' bits.
        pub const fn bits(self) -> u32 {
            self.0
        }

        /// The flags with these bits, if every bit is a flag.
        pub const fn from_bits(bits: u32) -> Option<OpenFlags> {
            if bits & !OpenFlags::ALL.0 == 0 { Some(OpenFlags(bits)) } else { None }
        }

        /// Whether every flag of `other` is set.
        pub const fn contains(self, other: OpenFlags) -> bool {
            self.0 & other.0 == other.0
        }

        /// The flags of both.
        pub const fn union(self, other: OpenFlags) -> OpenFlags {
            OpenFlags(self.0 | other.0)
        }

        /// The flags both have.
        pub const fn intersection(self, other: OpenFlags) -> OpenFlags {
            OpenFlags(self.0 & other.0)
        }

        /// Whether no flag is set.
        pub const fn is_empty(self) -> bool {
            self.0 == 0
        }
    }

