    /// Opens the file or directory at `path` (`.` for this one) and puts
    /// a capability to it with `rights` in slot `to`. Returns what it is.
    /// Needs the read right, and the write right to create or truncate or
    /// to ask for it.
    pub fn open<S: Syscalls + ?Sized>(sys: &S, cap: u32, path: &[u8], flags: OpenFlags, rights: capability::Rights, to: u32) -> Result<OpenResults, Status> {
        let words = OpenArgs { path: UserBuffer::of(path), flags, rights, to }.encode();
        let info = 0xb0001 | ((OpenArgs::WORDS as u64) << 32);
        let (status, out) = sys.syscall(
            syscalls::CAP_CALL,
            [cap as u64, info, words[0], words[1], words[2], words[3], words[4], words[5], words[6], words[7]],
        );
        if status != 0 {
            return Err(Status(status));
        }
        Ok(OpenResults::decode(&word_array::<8>(&out, 2))?)
    }

