    /// A network socket's option, which `socket_option` reads and sets, as
    /// POSIX's `getsockopt` and `setsockopt` name them. A boolean is 0 or 1.
    #[repr(u32)]
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub enum SocketOption {
        /// SO_REUSEADDR, a boolean. A port is free once the socket bound to
        /// it is closed, so it changes nothing, but it is kept.
        ReuseAddress = 1,
        /// SO_KEEPALIVE, a boolean: a stream socket's connection is probed
        /// after two hours without traffic, and reset if the other end has
        /// gone.
        KeepAlive = 2,
        /// TCP_NODELAY, a boolean: a stream socket sends small writes at once
        /// rather than gathering them (Nagle's algorithm).
        NoDelay = 3,
        /// SO_RCVBUF: the bytes the socket holds as they come. Setting it is
        /// taken, and changes nothing.
        ReceiveBuffer = 4,
        /// SO_SNDBUF: the bytes it holds as they go. Setting it is taken, and
        /// changes nothing.
        SendBuffer = 5,
        /// SO_ERROR, read only: why the last connection the socket tried
        /// failed, as a status word (0 for none), which reading clears.
        Error = 6,
        /// IP_TTL: how many routers its packets may pass, 1 to 255.
        TimeToLive = 7,
        /// SO_BROADCAST, a boolean, kept for datagram sockets.
        Broadcast = 8,
        /// SO_TYPE, read only: the socket's SocketType (radix-network(2)).
        Kind = 9,
        /// SO_RCVTIMEO: the most nanoseconds a receive or an accept waits, 0
        /// for no limit; one that waits longer fails with would_block.
        ReceiveTimeout = 10,
        /// SO_SNDTIMEO: likewise for a send, and for a stream socket's
        /// connect, which then fails with in_progress.
        SendTimeout = 11,
    }

    impl SocketOption {
        /// Every variant, in the order of their numbers.
        pub const ALL: [SocketOption; 11] = [
            SocketOption::ReuseAddress,
            SocketOption::KeepAlive,
            SocketOption::NoDelay,
            SocketOption::ReceiveBuffer,
            SocketOption::SendBuffer,
            SocketOption::Error,
            SocketOption::TimeToLive,
            SocketOption::Broadcast,
            SocketOption::Kind,
            SocketOption::ReceiveTimeout,
            SocketOption::SendTimeout,
        ];

        /// Its number.
        pub const fn raw(self) -> u32 {
            self as u32
        }

        /// The variant numbered `raw`.
        pub const fn from_raw(raw: u32) -> Option<SocketOption> {
            match raw {
                1 => Some(SocketOption::ReuseAddress),
                2 => Some(SocketOption::KeepAlive),
                3 => Some(SocketOption::NoDelay),
                4 => Some(SocketOption::ReceiveBuffer),
                5 => Some(SocketOption::SendBuffer),
                6 => Some(SocketOption::Error),
                7 => Some(SocketOption::TimeToLive),
                8 => Some(SocketOption::Broadcast),
                9 => Some(SocketOption::Kind),
                10 => Some(SocketOption::ReceiveTimeout),
                11 => Some(SocketOption::SendTimeout),
                _ => None,
            }
        }

        /// Its name in the interface definition.
        pub const fn name(self) -> &'static str {
            match self {
                SocketOption::ReuseAddress => "reuse_address",
                SocketOption::KeepAlive => "keep_alive",
                SocketOption::NoDelay => "no_delay",
                SocketOption::ReceiveBuffer => "receive_buffer",
                SocketOption::SendBuffer => "send_buffer",
                SocketOption::Error => "error",
                SocketOption::TimeToLive => "time_to_live",
                SocketOption::Broadcast => "broadcast",
                SocketOption::Kind => "kind",
                SocketOption::ReceiveTimeout => "receive_timeout",
                SocketOption::SendTimeout => "send_timeout",
            }
        }
    }

