    /// The label of the `read` method.
    pub const READ: u32 = 0x000c0001;

    /// The arguments of `read`.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct ReadArgs {
        /// `offset`.
        pub offset: u64,
        /// `buffer`.
        pub buffer: UserBuffer,
    }

    impl ReadArgs {
        /// How many words they take.
        pub const WORDS: usize = 3;

        /// Packs them into words.
        pub fn encode(&self) -> [u64; 8] {
            let mut words = [0u64; 8];
            words[0] = self.offset;
            words[1] = self.buffer.address;
            words[2] = self.buffer.len;
            words
        }

        /// Unpacks them from words, checking each.
        pub fn decode(words: &[u64; 8]) -> Result<ReadArgs, Invalid> {
            Ok(ReadArgs {
                offset: words[0],
                buffer: UserBuffer { address: words[1], len: words[2] },
            })
        }
    }

    /// The results of `read`.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct ReadResults {
        /// `count`.
        pub count: u64,
    }

    impl ReadResults {
        /// How many words they take.
        pub const WORDS: usize = 1;

        /// Packs them into words.
        pub fn encode(&self) -> [u64; 8] {
            let mut words = [0u64; 8];
            words[0] = self.count;
            words
        }

        /// Unpacks them from words, checking each.
        pub fn decode(words: &[u64; 8]) -> Result<ReadResults, Invalid> {
            Ok(ReadResults {
                count: words[0],
            })
        }
    }

    /// Reads from byte `offset` into `buffer`; returns how many bytes it
    /// read, fewer than asked at the end of the file. Needs the read right.
    pub fn read<S: Syscalls + ?Sized>(sys: &S, cap: u32, offset: u64, buffer: &mut [u8]) -> Result<ReadResults, Status> {
        let words = ReadArgs { offset, buffer: UserBuffer::of_mut(buffer) }.encode();
        let info = 0xc0001 | ((ReadArgs::WORDS as u64) << 32);
        let (status, out) = sys.syscall(
            syscalls::CAP_CALL,
            [cap as u64, info, words[0], words[1], words[2], words[3], words[4], words[5], words[6], words[7]],
        );
        if status != 0 {
            return Err(Status(status));
        }
        Ok(ReadResults::decode(&word_array::<8>(&out, 2))?)
    }

