pub mod notification {
    //! Notifications.
    //!
    //! A notification is a word of flags. `notify` sets the bits of the
    //! capability's badge in it and wakes a waiter; `wait` returns the word
    //! and clears it, waiting while it is 0. A ring can wait for one too,
    //! posting a completion when it is signalled (see radix-ring(2)).

    #[allow(unused_imports)]
    use super::*;

    /// Flags of the `wait` system call.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default)]
    pub struct WaitFlags(pub u64);

    impl WaitFlags {
        /// No flags.
        pub const NONE: WaitFlags = WaitFlags(0);
        /// Return at once, with would_block if the word is 0.
        pub const POLL: WaitFlags = WaitFlags(1);
        /// Every flag.
        pub const ALL: WaitFlags = WaitFlags(0x1);
        /// Each flag and its name.
        pub const NAMES: [(WaitFlags, &'static str); 1] = [
            (WaitFlags::POLL, "poll"),
        ];

        /// The flags' bits.
        pub const fn bits(self) -> u64 {
            self.0
        }

        /// The flags with these bits, if every bit is a flag.
        pub const fn from_bits(bits: u64) -> Option<WaitFlags> {
            if bits & !WaitFlags::ALL.0 == 0 { Some(WaitFlags(bits)) } else { None }
        }

        /// Whether every flag of `other` is set.
        pub const fn contains(self, other: WaitFlags) -> bool {
            self.0 & other.0 == other.0
        }

        /// The flags of both.
        pub const fn union(self, other: WaitFlags) -> WaitFlags {
            WaitFlags(self.0 | other.0)
        }

        /// The flags both have.
        pub const fn intersection(self, other: WaitFlags) -> WaitFlags {
            WaitFlags(self.0 & other.0)
        }

        /// Whether no flag is set.
        pub const fn is_empty(self) -> bool {
            self.0 == 0
        }
    }

    /// A word of flags that can be signalled and waited for. Signalling needs
    /// the send right, waiting the receive right.
    pub const INTERFACE: u16 = 0x0005;

    /// The interface's version.
    pub const VERSION: u32 = 1;
    /// The kind of object that answers it.
    pub const KIND: capability::ObjectKind = capability::ObjectKind::Notification;
}

