    /// What `wait` waits for, besides children that have ended.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default)]
    pub struct ChildWaitFlags(pub u32);

    impl ChildWaitFlags {
        /// No flags.
        pub const NONE: ChildWaitFlags = ChildWaitFlags(0);
        /// Return at once, with process 0, if no child has changed.
        pub const NO_HANG: ChildWaitFlags = ChildWaitFlags(1);
        /// Also report children that have stopped.
        pub const STOPPED: ChildWaitFlags = ChildWaitFlags(1 << 1);
        /// Also report children that have continued.
        pub const CONTINUED: ChildWaitFlags = ChildWaitFlags(1 << 2);
        /// Leave the child as it is, to be waited for again.
        pub const NO_REAP: ChildWaitFlags = ChildWaitFlags(1 << 3);
        /// Leave out children that have ended, for POSIX's `waitid` without
        /// WEXITED: only stops and continues are reported (since version 7).
        pub const SKIP_ENDED: ChildWaitFlags = ChildWaitFlags(1 << 4);
        /// Every flag.
        pub const ALL: ChildWaitFlags = ChildWaitFlags(0x1f);
        /// Each flag and its name.
        pub const NAMES: [(ChildWaitFlags, &'static str); 5] = [
            (ChildWaitFlags::NO_HANG, "no_hang"),
            (ChildWaitFlags::STOPPED, "stopped"),
            (ChildWaitFlags::CONTINUED, "continued"),
            (ChildWaitFlags::NO_REAP, "no_reap"),
            (ChildWaitFlags::SKIP_ENDED, "skip_ended"),
        ];

        /// The flags' bits.
        pub const fn bits(self) -> u32 {
            self.0
        }

        /// The flags with these bits, if every bit is a flag.
        pub const fn from_bits(bits: u32) -> Option<ChildWaitFlags> {
            if bits & !ChildWaitFlags::ALL.0 == 0 { Some(ChildWaitFlags(bits)) } else { None }
        }

        /// Whether every flag of `other` is set.
        pub const fn contains(self, other: ChildWaitFlags) -> bool {
            self.0 & other.0 == other.0
        }

        /// The flags of both.
        pub const fn union(self, other: ChildWaitFlags) -> ChildWaitFlags {
            ChildWaitFlags(self.0 | other.0)
        }

        /// The flags both have.
        pub const fn intersection(self, other: ChildWaitFlags) -> ChildWaitFlags {
            ChildWaitFlags(self.0 & other.0)
        }

        /// Whether no flag is set.
        pub const fn is_empty(self) -> bool {
            self.0 == 0
        }
    }

