    /// One entry of the array `poll` takes, as POSIX's `struct pollfd`.
    #[repr(C)]
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub struct PollEntry {
        /// The slot, less `poll`'s `base`; negative entries are passed over.
        pub fd: i32,
        /// The events to look for.
        pub events: u16,
        /// The events found, which `poll` writes.
        pub found: u16,
    }

    impl PollEntry {
        /// Its size in bytes.
        pub const SIZE: usize = 8;
        /// The offset of `fd`.
        pub const OFFSET_FD: usize = 0;
        /// The offset of `events`.
        pub const OFFSET_EVENTS: usize = 4;
        /// The offset of `found`.
        pub const OFFSET_FOUND: usize = 6;
    }

    const _: () = assert!(core::mem::size_of::<PollEntry>() == PollEntry::SIZE);
    const _: () = assert!(core::mem::offset_of!(PollEntry, fd) == PollEntry::OFFSET_FD);
    const _: () = assert!(core::mem::offset_of!(PollEntry, events) == PollEntry::OFFSET_EVENTS);
    const _: () = assert!(core::mem::offset_of!(PollEntry, found) == PollEntry::OFFSET_FOUND);

