    /// Where a process is in its life.
    #[repr(u8)]
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub enum ProcessState {
        /// Made, with no thread started yet.
        Created = 0,
        /// Its first thread has started, and it has not begun to end.
        Running = 1,
        /// Ending: its threads are stopping.
        Ending = 2,
        /// Ended, with an exit code. Deleting its last capability reaps it.
        Exited = 3,
    }

    impl ProcessState {
        /// Every variant, in the order of their numbers.
        pub const ALL: [ProcessState; 4] = [
            ProcessState::Created,
            ProcessState::Running,
            ProcessState::Ending,
            ProcessState::Exited,
        ];

        /// Its number.
        pub const fn raw(self) -> u8 {
            self as u8
        }

        /// The variant numbered `raw`.
        pub const fn from_raw(raw: u8) -> Option<ProcessState> {
            match raw {
                0 => Some(ProcessState::Created),
                1 => Some(ProcessState::Running),
                2 => Some(ProcessState::Ending),
                3 => Some(ProcessState::Exited),
                _ => None,
            }
        }

        /// Its name in the interface definition.
        pub const fn name(self) -> &'static str {
            match self {
                ProcessState::Created => "created",
                ProcessState::Running => "running",
                ProcessState::Ending => "ending",
                ProcessState::Exited => "exited",
            }
        }
    }

