    /// The byte arguments of the system call numbered `number`: for
    /// each, the argument register its address is in (its length is in
    /// the next), and whether the kernel writes it.
    pub const fn syscall_bytes(number: u64) -> &'static [(u8, bool)] {
        match number {
            11 => &[(1, false)],
            _ => &[],
        }
    }

